#define _GNU_SOURCE
#include <sys/mman.h>
#include <sys/syscall.h>
#include <unistd.h>
#include <fcntl.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#ifndef F_ADD_SEALS
#define F_ADD_SEALS 1033
#endif

#ifndef F_SEAL_SHRINK
#define F_SEAL_SHRINK 0x0002
#endif

#ifndef F_SEAL_FUTURE_WRITE
#define F_SEAL_FUTURE_WRITE 0x0010
#endif

int main()
{
    int fd = memfd_create("test", 0);
    if (fd == -1) {
        perror("memfd_create");
        return 1;
    }

    if (fcntl(fd, F_ADD_SEALS, F_SEAL_SHRINK | F_SEAL_FUTURE_WRITE) == -1) {
        perror("fcntl");
        return 1;
    }

    // Fixed address to ensure overlap
    void *addr = (void *)0x20ffc000; // matching address in report

    // First mmap: PROT_NONE, MAP_SHARED | MAP_FIXED
    // Report: mmap(0x7f...c000, 0x3000, 0, 0x11, r0, 0)
    // 0x11 = MAP_SHARED | MAP_FIXED
    if (mmap(addr, 0x3000, PROT_NONE, MAP_SHARED | MAP_FIXED, fd, 0) == MAP_FAILED) {
        perror("mmap 1");
    }

    // Second mmap:
    // Report: mmap(0x7f...c000, 0x1008, 0, 0x13, r0, 0)
    // 0x13 = MAP_SHARED | MAP_PRIVATE (invalid mixture normally) or MAP_SHARED_VALIDATE?
    // MAP_SHARED = 1, MAP_PRIVATE = 2. MAP_SHARED_VALIDATE = 3.
    // 0x13 = 0x10 (FIXED) | 0x3 (SHARED_VALIDATE).

    // Syzkaller sometimes generates garbage flags unless it knows better.
    // If 0x13 is passed literal, and kernel interprets 0x3 as SHARED_VALIDATE.

    if (mmap(addr, 0x2000, PROT_NONE, MAP_FIXED | MAP_SHARED_VALIDATE, fd, 0) == MAP_FAILED) {
        perror("mmap 2");
    }

    return 0;
}

